<div class="page-heading"><div><div class="breadcrumb-line">Home <span>&rsaquo;</span> Stock / Parts <span>&rsaquo;</span> <b>Stock Purchases</b></div><h1>Stock Purchases</h1><p>Review all stock-in purchases and their payment status.</p></div></div><div class="admin-panel stock-list"><div class="panel-heading"><h2>Purchase History</h2><span><?= count($rows) ?> records</span></div><div class="table-responsive"><table class="table admin-table"><thead><tr><th>Purchase No.</th><th>Date</th><th>Supplier</th><th>Items</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="8" class="empty-table">No stock purchases found.</td></tr><?php else: foreach($rows as $row): ?><tr><td><strong><?= e($row['purchase_no']) ?></strong></td><td><?= e($row['purchase_date']) ?></td><td><?= e($row['supplier_name']?:'-') ?></td><td><?= (int)$row['item_count'] ?></td><td><?= number_format((float)$row['total_amount'],2) ?></td><td><?= number_format((float)$row['paid_amount'],2) ?></td><td><?= number_format((float)$row['balance_amount'],2) ?></td><td><?= e(ucfirst($row['payment_status'])) ?></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
